const normalizePhone = (raw) => {
  let d = String(raw ?? "").replace(/\D/g, ""); // buang spasi, +, -, (), dll
  if (d.startsWith("620")) d = "62" + d.slice(3); // +62 0812... -> 62812...
  else if (d.startsWith("0")) d = "62" + d.slice(1); // 0812... -> 62812...
  else if (d.startsWith("8")) d = "62" + d;          // 812...  -> 62812...
  return /^628\d{8,11}$/.test(d) ? d : null;         // nomor seluler Indonesia
};

const out = [];
for (const item of $input.all()) {
  const data = item.json.body ?? item.json; // Webhook node menaruh payload di "body"
  const phone = normalizePhone(data.phone);
  if (!phone) continue; // format tidak valid -> di-drop

  out.push({
    json: {
      ...data,
      phone,
      lead_id: phone, // lead_id dibentuk dari nomor ternormalisasi
    },
  });
}
return out;
